def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid); w=len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            cells=[(r,c)]; seen.add((r,c))
            for x,y in cells:
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==grid[r][c]:
                        seen.add((a,b)); cells.append((a,b))
            comps.append(cells)
    markers=[p for p in comps if len(p)<(max(r for r,c in p)-min(r for r,c in p)+1)*(max(c for r,c in p)-min(c for r,c in p)+1)]
    if not markers: markers=[p for p in comps if grid[p[0][0]][p[0][1]]==3]
    if markers:
        cutoff=min(r for p in markers for r,c in p)
        for p in comps:
            if max(r for r,c in p)<cutoff:
                for r,c in p: out[r][c]=0
    return out

